const lessons=[{"sentences":[{"speaker":"A","text":"Good morning team please give a warm welcome to our newest office assistant who starts today.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.572},{"speaker":"A","text":"Since our reception desk is very busy this week she will sit temporarily on the third floor near the marketing department.","position":2,"audioStartSeconds":5.772,"audioEndSeconds":12.847541666666666},{"speaker":"A","text":"Please remember to introduce yourselves when you walk past her desk during your morning coffee break.","position":3,"audioStartSeconds":13.047541666666667,"audioEndSeconds":18.936708333333332},{"speaker":"A","text":"If you have any questions regarding her daily tasks please contact the human resources manager directly.","position":4,"audioStartSeconds":19.136708333333335,"audioEndSeconds":25.992375},{"speaker":"A","text":"She will join our regular weekly department meeting tomorrow afternoon so everyone can meet her properly.","position":5,"audioStartSeconds":26.192375,"audioEndSeconds":32.493916666666664},{"speaker":"A","text":"Thank you for your cooperation and support as we welcome new colleagues to our growing company.","position":6,"audioStartSeconds":32.69391666666667,"audioEndSeconds":38.27379166666667},{"speaker":"A","role":"section-start","text":"Attention everyone please take note of an important schedule change for this upcoming computer training session.","position":7,"audioStartSeconds":43.27379166666667,"audioEndSeconds":49.858875},{"speaker":"A","text":"Although we originally planned to meet in the main conference room we will gather in room four instead.","position":8,"audioStartSeconds":50.058875,"audioEndSeconds":55.8965},{"speaker":"A","text":"This larger space is necessary because extra software specialists from headquarters decided to join our workshop.","position":9,"audioStartSeconds":56.0965,"audioEndSeconds":63.14545833333333},{"speaker":"A","text":"Please bring your printed manuals and your employee ID badges so we can record your attendance quickly.","position":10,"audioStartSeconds":63.34545833333333,"audioEndSeconds":69.53104166666667},{"speaker":"A","text":"If you arrive after the session begins please enter quietly through the back door to avoid any disruption.","position":11,"audioStartSeconds":69.73104166666667,"audioEndSeconds":76.097},{"speaker":"A","text":"Please speak with your direct supervisor today if you cannot attend this mandatory afternoon professional development class.","position":12,"audioStartSeconds":76.297,"audioEndSeconds":83.55075}],"questions":[{"prompt":"What is the primary topic of the first announcement?","options":["Welcoming a new staff member.","Booking a conference room.","Reporting a software problem."],"answer":"A","evidenceSentence":1,"evidence":"warm welcome to our newest office assistant","explanation":"Thông báo mở đầu bằng việc chào đón nhân viên văn phòng mới."},{"prompt":"Where will the new assistant sit temporarily?","options":["On the first floor near reception.","On the third floor near marketing.","In the main conference room."],"answer":"B","evidenceSentence":2,"evidence":"sit temporarily on the third floor near the marketing department","explanation":"Cô ấy sẽ ngồi tạm thời ở tầng ba gần phòng marketing."},{"prompt":"When will everyone officially meet the new colleague?","options":["During the morning coffee break.","At tomorrow afternoon meeting.","Next Monday morning."],"answer":"B","evidenceSentence":5,"evidence":"join our regular weekly department meeting tomorrow afternoon","explanation":"Cô ấy sẽ tham gia cuộc họp phòng vào chiều mai."},{"prompt":"What is the main reason for the schedule change in the second talk?","options":["Extra software specialists are joining.","The main conference room is too cold.","The manager changed the training date."],"answer":"A","evidenceSentence":9,"evidence":"extra software specialists from headquarters decided to join","explanation":"Sự thay đổi phòng họp là do có thêm chuyên gia phần mềm tham gia."},{"prompt":"What item should attendees bring to the training session?","options":["A laptop and a notebook.","Printed manuals and ID badges.","Coffee and snacks."],"answer":"B","evidenceSentence":10,"evidence":"bring your printed manuals and your employee ID badges","explanation":"Người tham dự cần mang theo cẩm nang in sẵn và thẻ nhân viên."},{"prompt":"What should employees do if they cannot attend the training?","options":["Send an email to human resources.","Speak with their direct supervisor.","Call the training instructor."],"answer":"B","evidenceSentence":12,"evidence":"speak with your direct supervisor today","explanation":"Nhân viên cần nói chuyện với quản lý trực tiếp nếu không thể tham dự."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
